    dc=defaultdict(list)
    for r,c in ((r,c) for r in range(H) for c in range(W) if g[r][c]!=bg): dc[c].append(r)
    def fill(cells):
        rs_={q for q,_ in cells}; cs_={p for _,p in cells}
        lo,hi=min(rs_),max(rs_)
